TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"yes","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"yes","where":"Question 3"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"yes","where":"Question 5"},{"id":"R6","met":"yes","where":"Question 6"},{"id":"R7","met":"partial","where":null}],"technical_issues":[{"where":"Question 3","issue":"Component availabilities (0.9995, 0.999, 0.9995, 0.995) are used without being stated as assumptions or sourced, so the reader cannot verify the inputs."},{"where":"Question 2","issue":"The claim 'Five developers running eight or more services' assumes a service count that is not stated in the scenario or as an assumption."},{"where":"Question 5","issue":"An idempotency key prevents duplicate charges on retry; it is not a mechanism that enforces consistency during a partition, so it is a weak technique for the CP choice."},{"where":"Question 4","issue":"The claim that the breaker 'would have opened within seconds' is asserted without supporting data or stated assumptions."}],"overall":"Strong, technically accurate answers. Q3 calculations are correct to the required precision. Main deductions: no explicit assumptions section, several answers at or just over the 150-word limit, and a weak technique choice for the CP payment decision.","criteria":[{"id":"C1","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"Two attributes are chosen and tied to scenario facts (900 lunch orders, 4.2 s p95, payment slowdown). Both scenarios have all six parts, and both response measures are quantified and testable.","evidence":[{"where":"Question 1","quote":"Performance and availability matter most"},{"where":"Question 1","quote":"Response measure: the p95 response time is under 1.5 s and no requests are dropped."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"The modular monolith is clearly recommended. Trade-offs are tied to the five-developer team, the single-VM slowness and the weekly downtime. The downside is acknowledged. The unstated assumption of eight services slightly weakens it.","evidence":[{"where":"Question 2","quote":"The lunchtime slowness comes from a single virtual machine and is fixed by running several instances of the monolith behind a load balancer."},{"where":"Question 2","quote":"The downside I accept is that modules cannot be scaled independently and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Excellent","mark":8.0,"scale":8.0,"points":8.0,"max":8.0,"reasoning":"All three parts are correct on checking: (a) 99.30%, (b) 5.0 h, (c) 99.80% and 1.5 h. Working is shown at two decimal places. Component availabilities are not restated explicitly, which is a minor presentation gap.","evidence":[{"where":"Question 3","quote":"A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"},{"where":"Question 3","quote":"A_pay = 1 − (1 − 0.995)² = 1 − 0.000025 = 0.999975"}]},{"id":"C4","level":"Excellent","mark":5.0,"scale":5.0,"points":5.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern. Closed, Open and Half-Open states are explained correctly and applied to the 25-minute outage. Tuning and fallback drawbacks are both given.","evidence":[{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."},{"where":"Question 4","quote":"Tuning consideration: the threshold must come from real latency data."}]},{"id":"C5","level":"Excellent","mark":5.0,"scale":6.0,"points":5.0,"max":6.0,"reasoning":"CAP is used correctly, with both choices justified and a concrete technique for each (cache with TTL, idempotency key). The idempotency key addresses retry safety more than partition-time consistency, so it is a slightly weak fit.","evidence":[{"where":"Question 5","quote":"For payments I choose consistency (CP): the order is rejected with a clear error rather than risk an inconsistent charge."},{"where":"Question 5","quote":"This is the AP choice, with eventual consistency."}]},{"id":"C6","level":"Excellent","mark":5.0,"scale":5.0,"points":5.0,"max":5.0,"reasoning":"Context, Decision and Consequences are all present and specific to CampusEats. Both positive and negative consequences are given, including at-least-once delivery and the stuck-queue risk.","evidence":[{"where":"Question 6","quote":"Consequences (negative): The queue is one more component for five developers to run and monitor."},{"where":"Question 6","quote":"Context: After an order is paid, the application calls the outlet's tablet synchronously and waits for the reply."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Headings, IEEE citations and reference list are correct and the terminology is precise. Several answers (Q2, Q4, Q6) sit at or slightly above 150 words by my count, and no assumptions section is provided.","evidence":[{"where":"Question 4","quote":"Drawback: nobody can pay while it is open, so a fallback is needed."},{"where":"References","quote":"[2] M. T. Nygard, Release It! Design and Deploy Production-Ready Software, 2nd ed."}]}]}
